package com.schooloss.fullnative.feature.messages;
import android.os.Bundle;import android.view.*;import android.widget.*;import com.schooloss.fullnative.core.*;import org.json.*;
public final class ConversationActivity extends BaseActivity {
 private int id;@Override protected void onCreate(Bundle b){super.onCreate(b);id=getIntent().getIntExtra("id",0);loading("Opening conversation","Loading SchoolOS messages…");load();}
 private void load(){io.execute(()->{try{JSONObject r=api.get("message_thread","id="+id);JSONObject d=r.optJSONObject("data");runOnUiThread(()->render(d));}catch(Exception e){runOnUiThread(()->error("Could not open conversation",e,this::load));}});}
 private void render(JSONObject d){LinearLayout p=Ui.v(this);p.setPadding(Ui.dp(this,14),Ui.dp(this,12),Ui.dp(this,14),Ui.dp(this,24));p.setBackgroundColor(Constants.BG);TextView back=Ui.text(this,"‹  Messages",12,Constants.BLUE,true);back.setOnClickListener(v->finish());p.addView(back);p.addView(Ui.text(this,d==null?"Conversation":d.optString("subject","Conversation"),23,Constants.TEXT,true));p.addView(Ui.text(this,Ui.pretty(d==null?"open":d.optString("status","open")),10,Constants.MUTED,false));JSONArray ms=d==null?null:d.optJSONArray("messages");if(ms!=null)for(int i=0;i<ms.length();i++){JSONObject m=ms.optJSONObject(i);com.google.android.material.card.MaterialCardView c=Ui.card(this);LinearLayout in=Ui.v(this);in.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,10));in.addView(Ui.text(this,m.optBoolean("mine",false)?"You":m.optString("sender","User"),9,m.optBoolean("mine",false)?Constants.BLUE:Constants.MUTED,true));in.addView(Ui.text(this,m.optString("body",""),12,Constants.TEXT,false));c.addView(in);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT,ViewGroup.LayoutParams.WRAP_CONTENT);lp.topMargin=Ui.dp(this,7);p.addView(c,lp);}if(d!=null&&d.optBoolean("can_reply",false)){EditText reply=new EditText(this);reply.setHint("Write a reply…");reply.setMinLines(3);p.addView(Ui.gap(this,10));p.addView(reply);com.google.android.material.button.MaterialButton send=Ui.button(this,"Send Reply",Constants.BLUE,0xFFFFFFFF);send.setOnClickListener(v->send(reply));p.addView(send);}ScrollView sc=new ScrollView(this);sc.addView(p);setContentView(sc);}
 private void send(EditText e){String t=e.getText().toString().trim();if(t.isEmpty())return;loading("Sending reply","Delivering through SchoolOS…");io.execute(()->{try{JSONObject b=new JSONObject();b.put("conversation_id",id);b.put("body",t);api.post("message_reply",b);runOnUiThread(this::load);}catch(Exception x){runOnUiThread(()->error("Reply was not sent",x,this::load));}});}
}